CREATE POLICY lectura_cegada ON simulacion.etiquetas FOR SELECT TO semaforo_lectura USING (NOT EXISTS (SELECT 1 FROM control.escenarios_cegados AS cegado WHERE cegado.escenario_id = etiquetas.escenario_id));
ALTER TABLE simulacion.comparadores ENABLE ROW LEVEL SECURITY;
CREATE POLICY carga_ve_todo ON simulacion.comparadores TO semaforo_carga USING (true) WITH CHECK (true);
CREATE POLICY lectura_cegada ON simulacion.comparadores FOR SELECT TO semaforo_lectura USING (NOT EXISTS (SELECT 1 FROM control.escenarios_cegados AS cegado WHERE cegado.escenario_id = comparadores.escenario_id));
ALTER TABLE aprendizaje.metricas_modelo ENABLE ROW LEVEL SECURITY;
CREATE POLICY carga_ve_todo ON aprendizaje.metricas_modelo TO semaforo_carga USING (true) WITH CHECK (true);
CREATE POLICY lectura_cegada ON aprendizaje.metricas_modelo FOR SELECT TO semaforo_lectura USING (metricas_modelo.asignacion <> 'test' OR control.prueba_abierta(metricas_modelo.particion_id));
ALTER TABLE aprendizaje.errores_por_escenario ENABLE ROW LEVEL SECURITY;
CREATE POLICY carga_ve_todo ON aprendizaje.errores_por_escenario TO semaforo_carga USING (true) WITH CHECK (true);
CREATE POLICY lectura_cegada ON aprendizaje.errores_por_escenario FOR SELECT TO semaforo_lectura USING (NOT EXISTS (SELECT 1 FROM control.escenarios_cegados AS cegado WHERE cegado.escenario_id = errores_por_escenario.escenario_id));
ALTER TABLE aprendizaje.consultas ENABLE ROW LEVEL SECURITY;
CREATE POLICY carga_ve_todo ON aprendizaje.consultas TO semaforo_carga USING (true) WITH CHECK (true);
CREATE POLICY lectura_cegada ON aprendizaje.consultas FOR SELECT TO semaforo_lectura USING (consultas.escenario_id IS NULL OR NOT EXISTS (SELECT 1 FROM control.escenarios_cegados AS cegado WHERE cegado.escenario_id = consultas.escenario_id));
ALTER TABLE aprendizaje.consulta_tramos ENABLE ROW LEVEL SECURITY;
CREATE POLICY carga_ve_todo ON aprendizaje.consulta_tramos TO semaforo_carga USING (true) WITH CHECK (true);
CREATE POLICY lectura_cegada ON aprendizaje.consulta_tramos FOR SELECT TO semaforo_lectura USING (EXISTS (SELECT 1 FROM aprendizaje.consultas AS padre WHERE padre.request_id = consulta_tramos.request_id));
ALTER TABLE aprendizaje.consulta_reglas ENABLE ROW LEVEL SECURITY;
CREATE POLICY carga_ve_todo ON aprendizaje.consulta_reglas TO semaforo_carga USING (true) WITH CHECK (true);
CREATE POLICY lectura_cegada ON aprendizaje.consulta_reglas FOR SELECT TO semaforo_lectura USING (EXISTS (SELECT 1 FROM aprendizaje.consultas AS padre WHERE padre.request_id = consulta_reglas.request_id));
ALTER TABLE evaluacion.comparaciones ENABLE ROW LEVEL SECURITY;
CREATE POLICY carga_ve_todo ON evaluacion.comparaciones TO semaforo_carga USING (true) WITH CHECK (true);
CREATE POLICY lectura_cegada ON evaluacion.comparaciones FOR SELECT TO semaforo_lectura USING (NOT EXISTS (SELECT 1 FROM control.escenarios_cegados AS cegado WHERE cegado.escenario_id = comparaciones.escenario_id));
ALTER TABLE evaluacion.diferencias ENABLE ROW LEVEL SECURITY;
CREATE POLICY carga_ve_todo ON evaluacion.diferencias TO semaforo_carga USING (true) WITH CHECK (true);
CREATE POLICY lectura_cegada ON evaluacion.diferencias FOR SELECT TO semaforo_lectura USING (EXISTS (SELECT 1 FROM evaluacion.comparaciones AS a WHERE a.comparacion_id = diferencias.comparacion_a_id) AND EXISTS (SELECT 1 FROM evaluacion.comparaciones AS b WHERE b.comparacion_id = diferencias.comparacion_b_id));
ALTER TABLE evaluacion.indicadores ENABLE ROW LEVEL SECURITY;
CREATE POLICY carga_ve_todo ON evaluacion.indicadores TO semaforo_carga USING (true) WITH CHECK (true);
CREATE POLICY lectura_cegada ON evaluacion.indicadores FOR SELECT TO semaforo_lectura USING (EXISTS (SELECT 1 FROM control.hitos AS hito WHERE hito.tipo = 'test_opened' AND hito.experimento_id = indicadores.experimento_id));

-- Permisos (roles del diseño). El dueño de todo es semaforo_admin.
GRANT USAGE ON SCHEMA control, caso, experimento, simulacion, aprendizaje, evaluacion TO semaforo_carga;
GRANT USAGE ON SCHEMA control, caso, experimento, simulacion, aprendizaje, evaluacion, vistas TO semaforo_lectura;
GRANT SELECT, INSERT ON ALL TABLES IN SCHEMA control, caso, experimento, simulacion, aprendizaje, evaluacion TO semaforo_carga;
GRANT UPDATE ON control.cargas, control.conflictos TO semaforo_carga;
GRANT SELECT ON ALL TABLES IN SCHEMA control, caso, experimento, simulacion, aprendizaje, evaluacion, vistas TO semaforo_lectura;

-- El panel solo lee las vistas con filtro explícito de cegado, revisadas por separado.
